def dependency_order(graph):
    done = set()
    active = set()
    result = []
    def visit(node):
        if node in done:
            return
        if node in active:
            raise ValueError('cycle')
        active.add(node)
        for child in graph.get(node, []):
            visit(child)
        active.remove(node)
        done.add(node)
        result.append(node)
    for node in graph:
        visit(node)
    return result

