def reserve(stock, sku, qty):
    if type(qty) is not int or qty < 1:
        raise ValueError('invalid quantity')
    if stock.get(sku, 0) < qty:
        raise ValueError('insufficient stock')
    stock[sku] -= qty
    return stock[sku]

